import { z } from 'zod/v3';

export type RuntimeActivity = 'idle' | 'busy' | 'unknown';

const depth = z.object({
  queued: z.number().int().nonnegative(),
  leased: z.number().int().nonnegative(),
});
const work = z.object({
  status: z.enum(['pending', 'running', 'succeeded', 'failed', 'cancelled']),
});
const activitySchema = z.object({
  session: z.object({
    status: z.enum(['IDLE', 'WATCHING', 'APPLYING', 'READY']),
  }),
  activeRun: z.unknown().refine((value) => value !== undefined),
  queue: z.object({
    apply: depth,
    variant: depth,
    queued: z.array(z.unknown()),
    leases: z.array(z.unknown()),
  }),
  variants: z.discriminatedUnion('active', [
    z.object({ active: z.literal(false), starting: z.boolean() }),
    z.object({
      active: z.literal(true),
      starting: z.boolean(),
      stage: z.enum([
        'awaiting_source_plan',
        'awaiting_briefs',
        'awaiting_approval',
        'work_items_ready',
        'waiting_for_results',
        'ready',
        'degraded',
        'failed',
        'cancelled',
      ]),
      variants: z.array(work),
      hostWork: z.array(work).optional(),
    }),
  ]),
});
const terminalStages = new Set(['ready', 'degraded', 'failed', 'cancelled']);
const isExecuting = ({ status }: z.infer<typeof work>): boolean =>
  status === 'pending' || status === 'running';

export const classifyRuntimeActivity = (input: unknown): RuntimeActivity => {
  const parsed = activitySchema.safeParse(input);
  if (!parsed.success) return 'unknown';
  const { session, activeRun, queue, variants } = parsed.data;
  if (
    session.status === 'APPLYING' ||
    activeRun !== null ||
    variants.starting ||
    queue.apply.queued +
      queue.apply.leased +
      queue.variant.queued +
      queue.variant.leased >
      0 ||
    queue.queued.length > 0 ||
    queue.leases.length > 0
  )
    return 'busy';
  if (
    variants.active &&
    (!terminalStages.has(variants.stage) ||
      variants.variants.some(isExecuting) ||
      variants.hostWork?.some(isExecuting))
  )
    return 'busy';
  return 'idle';
};
